            () => Array(k + 1).fill(-Infinity)));

    dp[0][0] = Array(k + 1).fill(0);

    for (let row = 0; row < m; row++) {
        const hasPrevRow = row > 0;

        for (let col = 0; col < n; col++) {
            if (row === 0 && col === 0) {
                continue;
            }

            const hasPrevCol = col > 0;

            const score = grid[row][col];
