                    hasPrevRow ? dp[row - 1][col][nkc] : -Infinity,
                    hasPrevCol ? dp[row][col - 1][nkc] : -Infinity,
                ) + score);

                if (dp[row][col][kc] === -Infinity) {
                    break;
                }
            }
        }
    }

